  /**
   * Check that the number given as {@code digits} is at most {@code limit}.
   *
   * <p>Both {@code digits} and {@code limit} are expected to be decimal digits without a sign and
   * without leading zeros. An empty text represents zero.
   *
   * <p>We compare the numbers as strings, since they might not fit into an integer. The digits of
   * numbers of equal length are ordered as the numbers themselves.
   *
   * @param digits Number to be checked
   * @param limit Largest allowed number
   * @return True if {@code digits} is at most {@code limit}
   */
  private static Boolean isMagnitudeAtMost(String digits, String limit) {
    if (StringHelpers.len(digits) != StringHelpers.len(limit)) {
      return (StringHelpers.len(digits) < StringHelpers.len(limit));
    }
    return (StringHelpers.compareByCodePoints(digits, limit) <= 0);
  }

  /**
   * Check that the integer {@code text} is within the given range.
   *
   * <p>The {@code text} is expected to consist of decimal digits with an optional sign.
   *
   * @param text Text to be checked
   * @param maxNegative Largest allowed magnitude of a negative number
   * @param maxPositive Largest allowed positive number
   * @return True if the {@code text} is within the range
   */
  private static Boolean isIntegerInRange(String text, String maxNegative, String maxPositive) {
    var digits = (StringHelpers.lstrip(StringHelpers.lstrip(text, "+-"), "0"));
    if (text.startsWith("-")) {
      return isMagnitudeAtMost(digits, maxNegative);
    }
    return isMagnitudeAtMost(digits, maxPositive);
  }

  /**
   * Check that the magnitude of the decimal {@code text} is below {@code limit}.
   *
   * <p>The {@code text} is expected to match the pattern of a finite {@code xs:double} or {@code
   * xs:float}, <em>i.e.</em>, a decimal with an optional sign, an optional point and an optional
   * exponent. The {@code limit} is expected to be a positive integer without leading zeros.
   *
   * <p>We compare the numbers as strings, since they do not necessarily fit into any native number,
   * and parsing them to floating-point numbers would round them.
   *
   * @param text Decimal to be checked
   * @param limit Exclusive upper bound on the magnitude
   * @return True if the magnitude of {@code text} is below {@code limit}
   */
  private static Boolean isDecimalMagnitudeBelow(String text, String limit) {
    var unsigned = StringHelpers.lstrip(text, "+-");
    long exponentStart = StringHelpers.find(unsigned, "e");
    if (exponentStart == -1) {
      exponentStart = StringHelpers.find(unsigned, "E");
    }
    var mantissa = unsigned;
    var exponentText = "";
    if (exponentStart != -1) {
      mantissa = StringHelpers.slice(unsigned, 0, exponentStart);
      exponentText = StringHelpers.slice(unsigned, exponentStart + 1);
    }
    long point = StringHelpers.find(mantissa, ".");
    var integerPart = mantissa;
    var fractionPart = "";
    if (point != -1) {
      integerPart = StringHelpers.slice(mantissa, 0, point);
      fractionPart = StringHelpers.slice(mantissa, point + 1);
    }
    var head = StringHelpers.lstrip(integerPart, "0");
    var tail = fractionPart;
    long shift = StringHelpers.len(head);
    if (Objects.equals(head, "")) {
      tail = StringHelpers.lstrip(fractionPart, "0");
      if (Objects.equals(tail, "")) {
        return true;
      }
      shift = (StringHelpers.len(tail) - StringHelpers.len(fractionPart));
    }
    var exponentDigits = (StringHelpers.lstrip(StringHelpers.lstrip(exponentText, "+-"), "0"));
    if (StringHelpers.len(exponentDigits) > 15) {
      return exponentText.startsWith("-");
    }
    long exponent = 0;
    if (StringHelpers.len(exponentDigits) > 0) {
      exponent = StringHelpers.parseSafeInt(exponentDigits);
      if (exponentText.startsWith("-")) {
        exponent = -exponent;
      }
    }
    long magnitude = exponent + shift;
    if (magnitude != StringHelpers.len(limit)) {
      return magnitude < StringHelpers.len(limit);
    }
    return (StringHelpers.compareByCodePoints(head + tail, limit) < 0);
  }

  /**
   * Check that {@code text} is a valid {@code xs:double}.
   *
   * <p>We check that the {@code text} matches the pattern of {@code xs:double}, and that it does
   * not overflow, <em>i.e.</em>, that it does not round to infinity unless it is {@code INF} or
   * {@code -INF}. See {@link aas_core.aas3_2.constants.Constants#xsDoubleOverflowThreshold}.
   *
   * <p>See: <a
   * href='https%3A//www.w3.org/TR/xmlschema-2/%23double'>https://www.w3.org/TR/xmlschema-2/#double</a>
   *
   * @param text Text to be checked
   * @return True if the {@code text} is a valid {@code xs:double}
   */
  public static Boolean isXsDouble(String text) {
    if (!matchesXsDouble(text)) {
      return false;
    }
    switch (text) {
      case "INF", "-INF", "NaN" -> {
        return true;
      }
    }
    return (isDecimalMagnitudeBelow(text, Constants.xsDoubleOverflowThreshold));
  }

