  /**
   * Check that the {@link aas_core.aas3_2.types.impl.DataSpecificationIec61360#getDefinition()} is
   * defined for all data specifications whose content is given as IEC 61360 at least in English.
   */
  public static Boolean dataSpecificationIec61360sHaveDefinitionAtLeastInEnglish(
      List<IEmbeddedDataSpecification> embeddedDataSpecifications) {
    for (var dataSpecification : embeddedDataSpecifications) {
      var content = dataSpecification.getDataSpecificationContent();
      if (!(content instanceof IDataSpecificationIec61360)) {
        continue;
      }
      var definition = (((IDataSpecificationIec61360) content).getDefinition());
      if (!definition.isPresent()) {
        return false;
      }
      if (!(definition.get().stream()
          .anyMatch(langString -> isBcp47ForEnglish(langString.getLanguage())))) {
        return false;
      }
    }
    return true;
  }

  private static Pattern constructIsBcp47ForEnglish() {
    String pattern = "^(en|EN)(-.*)?$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexIsBcp47ForEnglish = constructIsBcp47ForEnglish();

  /** Check that the {@code text} corresponds to a BCP47 code for english. */
  public static Boolean isBcp47ForEnglish(String text) {
    return regexIsBcp47ForEnglish.matcher(text).matches();
  }

  private static Pattern constructMatchesPathItem() {
    String pattern =
        "^(([A-Za-z][A-Za-z0-9_]+)|(\\[[0-9]+\\]))((\\.[A-Za-z][A-Za-z0-9_]+)|(\\[[0-9]+\\]))*$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesPathItem = constructMatchesPathItem();

  /**
   * Check that {@code text} is a valid idShortPath.
   *
   * <p>An idShortPath is a chain of idShorts or SubmodelElementList-indexes which points to an
   * element within a hierarchy of elements, <em>e.g.</em>, {@code sme1.sme2[0].p1}.
   */
  public static Boolean matchesPathItem(String text) {
    return regexMatchesPathItem.matcher(text).matches();
  }

  private static Pattern constructMatchesFieldIdentifier() {
    String arrayIndex = "(0|[1-9][0-9]*)";
    String optionalIndex = "\\[" + arrayIndex + "?\\]";
    String referenceClause = "(type|keys" + optionalIndex + "\\.(type|value))";
    String semanticIdClause = "semanticId(\\." + referenceClause + ")?";
    String supplementalSemanticIdClause =
        "supplementalSemanticIds(" + optionalIndex + ")?(\\." + referenceClause + ")?";
    String specificAssetIdsClause =
        "specificAssetIds"
            + optionalIndex
            + "\\.(name|value|externalSubjectId(\\."
            + referenceClause
            + ")?)";
    String endpointClause =
        "endpoints" + optionalIndex + "\\.(interface|protocolinformation\\.href)";
    String smDescriptorClause =
        "("
            + semanticIdClause
            + "|"
            + supplementalSemanticIdClause
            + "|idShort|id|"
            + endpointClause
            + ")";
    String idShort = "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?";
    String idShortPathSegment = idShort + "(" + optionalIndex + ")*";
    String idShortPath = idShortPathSegment + "(\\." + idShortPathSegment + ")*";
    String fieldsAas =
        "(idShort|id|assetInformation\\.assetKind|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\."
            + specificAssetIdsClause
            + "|submodels"
            + optionalIndex
            + "(\\."
            + referenceClause
            + ")?)";
    String fieldsSm = "(" + semanticIdClause + "|" + supplementalSemanticIdClause + "|idShort|id)";
    String fieldsSme =
        "("
            + semanticIdClause
            + "|"
            + supplementalSemanticIdClause
            + "|idShort|value|valueType|language)";
    String fieldsCd = "(idShort|id)";
    String fieldsAasDescriptor =
        "(idShort|id|assetKind|assetType|globalAssetId|"
            + specificAssetIdsClause
            + "|"
            + endpointClause
            + "|submodelDescriptors"
            + optionalIndex
            + "\\."
            + smDescriptorClause
            + ")";
    String pattern =
        "^(\\$aas#"
            + fieldsAas
            + "|\\$sm#"
            + fieldsSm
            + "|\\$sme(\\."
            + idShortPath
            + ")?#"
            + fieldsSme
            + "|\\$cd#"
            + fieldsCd
            + "|\\$aasdesc#"
            + fieldsAasDescriptor
            + "|\\$smdesc#"
            + smDescriptorClause
            + ")$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesFieldIdentifier = constructMatchesFieldIdentifier();

  /**
   * Check that {@code text} is a valid field identifier of the query language.
   *
   * <p>A field identifier starts with a root ({@code $aas}, {@code $sm}, {@code $sme}, {@code $cd},
   * {@code $aasdesc} or {@code $smdesc}), optionally followed by an idShortPath in case of {@code
   * $sme}, and ends with an attribute declaration after {@code #}, <em>e.g.</em>, {@code
   * $sme.someCollection.someProperty#value}.
   *
   * <p>See: <a
   * href='https%3A//industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html%23query-grammar'>https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar</a>
   *
   * @param text Text to be checked
   * @return True if the {@code text} conforms to the pattern
   */
  public static Boolean matchesFieldIdentifier(String text) {
    return regexMatchesFieldIdentifier.matcher(text).matches();
  }

  private static Pattern constructMatchesFragmentFieldIdentifier() {
    String arrayIndex = "(0|[1-9][0-9]*)";
    String optionalIndex = "\\[" + arrayIndex + "?\\]";
    String referenceClause = "keys(" + optionalIndex + ")?";
    String semanticIdClause = "semanticId(\\." + referenceClause + ")?";
    String supplementalSemanticIdClause =
        "supplementalSemanticIds(" + optionalIndex + "(\\." + referenceClause + ")?)?";
    String specificAssetIdsClause =
        "specificAssetIds("
            + optionalIndex
            + "(\\.externalSubjectId(\\."
            + referenceClause
            + ")?)?)?";
    String submodelsClause = "submodels(" + optionalIndex + "(\\." + referenceClause + ")?)?";
    String endpointClause = "endpoints(" + optionalIndex + ")?";
    String smDescriptorClause =
        "("
            + semanticIdClause
            + "|"
            + supplementalSemanticIdClause
            + "|idShort|"
            + endpointClause
            + ")";
    String submodelDescriptorsClause =
        "submodelDescriptors(" + optionalIndex + "(\\." + smDescriptorClause + ")?)?";
    String idShort = "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?";
    String idShortPathSegment = idShort + "(" + optionalIndex + ")*";
    String idShortPath = idShortPathSegment + "(\\." + idShortPathSegment + ")*";
    String fieldsAas =
        "(idShort|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\."
            + specificAssetIdsClause
            + "|"
            + submodelsClause
            + ")";
    String fieldsSm = "(" + semanticIdClause + "|" + supplementalSemanticIdClause + "|idShort)";
    String fieldsSme =
        "("
            + semanticIdClause
            + "|"
            + supplementalSemanticIdClause
            + "|idShort|value|valueType|language)";
    String fieldsAasDescriptor =
        "(idShort|description|displayName|extension|administration|assetKind|assetType|globalAssetId|"
            + specificAssetIdsClause
            + "|"
            + endpointClause
            + "|"
            + submodelDescriptorsClause
            + ")";
    String pattern =
        "^(\\$aas#"
            + fieldsAas
            + "|\\$sm#"
            + fieldsSm
            + "|\\$sme(\\."
            + idShortPath
            + ")?(#"
            + fieldsSme
            + ")?|\\$cd#idShort|\\$aasdesc#"
            + fieldsAasDescriptor
            + "|\\$smdesc#"
            + smDescriptorClause
            + ")$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesFragmentFieldIdentifier =
      constructMatchesFragmentFieldIdentifier();

  /**
   * Check that {@code text} is a valid fragment field identifier.
   *
   * <p>A fragment field identifier points to the part of the returned data which should be
   * filtered, <em>e.g.</em>, {@code $aas#assetInformation.specificAssetIds[]} or {@code
   * $sme.someCollection}.
   *
   * <p>See: <a
   * href='https%3A//industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html%23query-grammar'>https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar</a>
   *
   * @param text Text to be checked
   * @return True if the {@code text} conforms to the pattern
   */
  public static Boolean matchesFragmentFieldIdentifier(String text) {
    return regexMatchesFragmentFieldIdentifier.matcher(text).matches();
  }

  private static Pattern constructMatchesHexLiteral() {
    String pattern = "^16#[0-9A-F]+$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesHexLiteral = constructMatchesHexLiteral();

  /**
   * Check that {@code text} is a valid hexadecimal literal of the query language.
   *
   * <p>A hexadecimal literal is prefixed with {@code 16#}, <em>e.g.</em>, {@code 16#1F}.
   *
   * @param text Text to be checked
   * @return True if the {@code text} conforms to the pattern
   */
  public static Boolean matchesHexLiteral(String text) {
    return regexMatchesHexLiteral.matcher(text).matches();
  }

  private static Pattern constructMatchesDateTimeLiteral() {
    String digit = "[0-9]";
    String monthWith31Days = "(0[13578]|1[02])-(0[1-9]|[12]" + digit + "|3[01])";
    String monthWith30Days = "(0[469]|11)-(0[1-9]|[12]" + digit + "|30)";
    String february = "02-(0[1-9]|1" + digit + "|2[0-8])";
    String commonDate =
        digit + "{4}-(" + monthWith31Days + "|" + monthWith30Days + "|" + february + ")";
    String leapYear =
        "(" + digit + "{2}(0[48]|[2468][048]|[13579][26])|([02468][048]|[13579][26])00)";
    String leapDay = leapYear + "-02-29";
    String time =
        "(([01]"
            + digit
            + "|2[0-3]):[0-5]"
            + digit
            + "(:[0-5]"
            + digit
            + ")?(\\."
            + digit
            + "+)?|24:00(:00)?(\\.0+)?)";
    String timezone = "(Z|[+-]((0" + digit + "|1[0-3]):[0-5]" + digit + "|14:00))";
    String pattern = "^((" + commonDate + ")|(" + leapDay + "))T?" + time + timezone + "?$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesDateTimeLiteral = constructMatchesDateTimeLiteral();

  /**
   * Check that {@code text} is a valid date-time literal of the query language.
   *
   * <p>A date-time literal is a valid calendar date, followed by an optional {@code T} separator,
   * the time and an optional time zone, <em>e.g.</em>, {@code 2024-02-29T12:00:00Z}.
   *
   * @param text Text to be checked
   * @return True if the {@code text} conforms to the pattern
   */
  public static Boolean matchesDateTimeLiteral(String text) {
    return regexMatchesDateTimeLiteral.matcher(text).matches();
  }

  private static Pattern constructMatchesTimeLiteral() {
    String digit = "[0-9]";
    String time =
        "(([01]"
            + digit
            + "|2[0-3]):[0-5]"
            + digit
            + "(:[0-5]"
            + digit
            + ")?(\\."
            + digit
            + "+)?|24:00(:00)?(\\.0+)?)";
    String timezone = "(Z|[+-]((0" + digit + "|1[0-3]):[0-5]" + digit + "|14:00))";
    String pattern = "^" + time + timezone + "?$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesTimeLiteral = constructMatchesTimeLiteral();

  /**
   * Check that {@code text} is a valid time literal of the query language.
   *
   * <p>A time literal is given as {@code HH:MM}, {@code HH:MM:SS}, optionally with fractional
   * seconds and an optional time zone, <em>e.g.</em>, {@code 12:00:00+01:00}.
   *
   * @param text Text to be checked
   * @return True if the {@code text} conforms to the pattern
   */
  public static Boolean matchesTimeLiteral(String text) {
    return regexMatchesTimeLiteral.matcher(text).matches();
  }

  private static Pattern constructMatchesReferenceIdentifier() {
    String arrayIndex = "(0|[1-9][0-9]*)";
    String optionalIndex = "\\[" + arrayIndex + "?\\]";
    String referenceClause = "(type|keys" + optionalIndex + "\\.(type|value))";
    String semanticIdClause = "semanticId(\\." + referenceClause + ")?";
    String supplementalSemanticIdClause =
        "supplementalSemanticIds(" + optionalIndex + ")?(\\." + referenceClause + ")?";
    String specificAssetIdsClause =
        "specificAssetIds"
            + optionalIndex
            + "\\.(name|value|externalSubjectId(\\."
            + referenceClause
            + ")?)";
    String idShort = "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?";
    String idShortPathSegment = idShort + "(" + optionalIndex + ")*";
    String idShortPath = idShortPathSegment + "(\\." + idShortPathSegment + ")*";
    String identifierCharacter =
        "([\\x{09}\\x{0a}\\x{0d}\\x{20}-\\x{21}\\x{23}-\\x{5b}\\x{5d}-\\x{d7ff}\\x{e000}-\\x{fffd}\\x{10000}-\\x{10ffff}]|\\\\[\"\\\\])";
    String identifierInstance = "\\(\"" + identifierCharacter + "+\"\\)";
    String fieldsAas =
        "(idShort|id|assetInformation\\.assetKind|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\."
            + specificAssetIdsClause
            + "|submodels"
            + optionalIndex
            + "(\\."
            + referenceClause
            + ")?)";
    String fieldsSm = "(" + semanticIdClause + "|" + supplementalSemanticIdClause + "|idShort|id)";
    String fieldsSme =
        "("
            + semanticIdClause
            + "|"
            + supplementalSemanticIdClause
            + "|idShort|value|valueType|language)";
    String pattern =
        "^(\\$aas"
            + identifierInstance
            + "#"
            + fieldsAas
            + "|\\$sm"
            + identifierInstance
            + "#"
            + fieldsSm
            + "|\\$cd"
            + identifierInstance
            + "#(idShort|id)|\\$sme"
            + identifierInstance
            + "\\."
            + idShortPath
            + "#"
            + fieldsSme
            + ")$";
    return Pattern.compile(pattern);
  }

  private static final Pattern regexMatchesReferenceIdentifier =
      constructMatchesReferenceIdentifier();

  /**
   * Check that {@code text} is a valid reference identifier.
   *
   * <p>A reference identifier points to an attribute of a specific instance given by its
   * identifier, <em>e.g.</em>, {@code $sm("https://example.com/sm")#idShort} or {@code
   * $sme("https://example.com/sm").someProperty#value}. A quotation mark and a reverse solidus in
   * the identifier are escaped as {@code \"} and {@code \\}, respectively.
   *
   * <p>See: <a
   * href='https%3A//industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html%23query-grammar'>https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar</a>
   *
   * @param text Text to be checked
   * @return True if the {@code text} conforms to the pattern
   */
  public static Boolean matchesReferenceIdentifier(String text) {
    return regexMatchesReferenceIdentifier.matcher(text).matches();
  }

  /**
   * Check that {@code value} can be used as an operand of {@code valueType}.
   *
   * <p>Following the normative JSON schema of the query language, a field is implicitly cast to the
   * type of the other operand, and can hence be used as an operand of any type. A global attribute
   * giving a date and time ({@code LOCALNOW}, {@code UTCNOW} or {@code CLIENTNOW}) can be used both
   * as a string and as a date-time, while all the other attributes are strings.
   *
   * <p>See: <a
   * href='https%3A//industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html%23_json_schema'>https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema</a>
   *
   * @param value Operand of a comparison
   * @param valueType One of {@code string}, {@code number}, {@code hex}, {@code boolean}, {@code
   *     date_time} or {@code time}
   * @return True if {@code value} can be used as {@code valueType}
   */
  private static Boolean canBeOfType(Value value, String valueType) {
    if (value.getUnderlying() instanceof IFieldOperand) {
      return true;
    }
    if (value.getUnderlying() instanceof IAttributeOperand) {
      if (Objects.equals(valueType, "string")) {
        return true;
      }
      var attribute = (((IAttributeOperand) value.getUnderlying()).getAttribute());
      return Objects.equals(valueType, "date_time")
          && attribute.getUnderlying() instanceof IGlobalAttribute
          && (((IGlobalAttribute) attribute.getUnderlying()).getKind()
                  == GlobalAttributeKind.LOCAL_NOW
              || ((IGlobalAttribute) attribute.getUnderlying()).getKind()
                  == GlobalAttributeKind.UTC_NOW
              || ((IGlobalAttribute) attribute.getUnderlying()).getKind()
                  == GlobalAttributeKind.CLIENT_NOW);
    }
    if ((value.getUnderlying() instanceof IStringLiteral
        || value.getUnderlying() instanceof IStringCast)) {
      return Objects.equals(valueType, "string");
    }
    if ((value.getUnderlying() instanceof INumberLiteral
        || value.getUnderlying() instanceof INumberCast
        || value.getUnderlying() instanceof IDayOfWeek
        || value.getUnderlying() instanceof IDayOfMonth
        || value.getUnderlying() instanceof IMonth
        || value.getUnderlying() instanceof IYear)) {
      return Objects.equals(valueType, "number");
    }
    if ((value.getUnderlying() instanceof IHexLiteral
        || value.getUnderlying() instanceof IHexCast)) {
      return Objects.equals(valueType, "hex");
    }
    if ((value.getUnderlying() instanceof IBooleanLiteral
        || value.getUnderlying() instanceof IBooleanCast)) {
      return Objects.equals(valueType, "boolean");
    }
    if ((value.getUnderlying() instanceof IDateTimeLiteral
        || value.getUnderlying() instanceof IDateTimeCast)) {
      return Objects.equals(valueType, "date_time");
    }
    if ((value.getUnderlying() instanceof ITimeLiteral
        || value.getUnderlying() instanceof ITimeCast)) {
      return Objects.equals(valueType, "time");
    }
    return false;
  }

  /**
   * Check that {@code left} and {@code right} can be compared for (in)equality.
   *
   * <p>Following the normative JSON schema of the query language, the two operands need to be of
   * the same type: a string, a number, a hexadecimal, a boolean, a date-time or a time. A field is
   * implicitly cast to the type of the other operand, and can hence be compared with an operand of
   * any type. A global attribute giving a date and time ({@code LOCALNOW}, {@code UTCNOW} or {@code
   * CLIENTNOW}) can be used both as a string and as a date-time.
   *
   * <p>See: <a
   * href='https%3A//industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html%23_json_schema'>https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema</a>
   *
   * @param left First operand of the comparison
   * @param right Second operand of the comparison
   * @return True if the operands can be compared for (in)equality
   */
  public static Boolean areEqualityComparable(Value left, Value right) {
    return (canBeOfType(left, "string") && canBeOfType(right, "string"))
        || (canBeOfType(left, "number") && canBeOfType(right, "number"))
        || (canBeOfType(left, "hex") && canBeOfType(right, "hex"))
        || (canBeOfType(left, "boolean") && canBeOfType(right, "boolean"))
        || (canBeOfType(left, "date_time") && canBeOfType(right, "date_time"))
        || (canBeOfType(left, "time") && canBeOfType(right, "time"));
  }

  /**
   * Check that {@code left} and {@code right} can be compared by order.
   *
   * <p>The operands need to be comparable for (in)equality (see {@code are_equality_comparable}),
   * but booleans can not be ordered.
   *
   * <p>See: <a
   * href='https%3A//industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html%23_json_schema'>https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema</a>
   *
   * @param left First operand of the comparison
   * @param right Second operand of the comparison
   * @return True if the operands can be compared by order
   */
  public static Boolean areOrderComparable(Value left, Value right) {
    return areEqualityComparable(left, right)
        && (!(left.getUnderlying() instanceof IBooleanLiteral
            || left.getUnderlying() instanceof IBooleanCast))
        && (!(right.getUnderlying() instanceof IBooleanLiteral
            || right.getUnderlying() instanceof IBooleanCast));
  }

