    @Override
    public Stream<Reporting.Error> transformAssetInformation(IAssetInformation that) {
      Stream<Reporting.Error> errorStream = Stream.empty();
      final Optional<List<ISpecificAssetId>> thatSpecificAssetIds = that.getSpecificAssetIds();
      final Optional<String> thatGlobalAssetId = that.getGlobalAssetId();
      final Optional<String> thatAssetType = that.getAssetType();
      final Optional<IResource> thatDefaultThumbnail = that.getDefaultThumbnail();
      if (!(!(thatSpecificAssetIds.isPresent())
          || (thatSpecificAssetIds.get().stream()
              .allMatch(
                  specificAssetId ->
                      !specificAssetIdNameMatchesGlobalAssetId(specificAssetId.getName())
                          || ((thatGlobalAssetId.isPresent())
                              && Objects.equals(
                                  specificAssetId.getValue(), thatGlobalAssetId.get())))))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-116: ``globalAssetId`` (case-insensitive) "
                            + "is a reserved key. If used as value for the name of "
                            + "specific asset ID then the value of specific asset ID shall "
                            + "be identical to the global asset ID with semantics as "
                            + "defined in "
                            + "https://admin-shell.io/aas/3/x/AssetInformation/globalAssetId, "
                            + "x being the minor version of the used specification.")));
      }
      if (!(((thatGlobalAssetId.isPresent()) || (thatSpecificAssetIds.isPresent()))
          && (!(thatSpecificAssetIds.isPresent()) || (thatSpecificAssetIds.get().size() >= 1)))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-131: Either the global asset ID shall be "
                            + "defined or at least one specific asset ID.")));
      }
      if (!(!(thatSpecificAssetIds.isPresent()) || (thatSpecificAssetIds.get().size() >= 1))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Specific asset IDs must be either not set or have at least "
                            + "one item.")));
      }
      errorStream =
          Stream.<Reporting.Error>concat(
              errorStream,
              Stream.of(that.getAssetKind())
                  .flatMap(Verification::verifyAssetKind)
                  .map(
                      error -> {
                        error.prependSegment(new Reporting.NameSegment("assetKind"));
                        return error;
                      }));
      if (thatGlobalAssetId.isPresent()) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(thatGlobalAssetId.get())
                    .flatMap(Verification::verifyIdentifier)
                    .map(
                        error -> {
                          error.prependSegment(new Reporting.NameSegment("globalAssetId"));
                          return error;
                        }));
      }
      if (thatSpecificAssetIds.isPresent()) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(thatSpecificAssetIds.get())
                    .flatMap(Verification::verifyListOf_ISpecificAssetId)
                    .map(
                        error -> {
                          error.prependSegment(new Reporting.NameSegment("specificAssetIds"));
                          return error;
                        }));
      }
      if (thatAssetType.isPresent()) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(thatAssetType.get())
                    .flatMap(Verification::verifyIdentifier)
                    .map(
                        error -> {
                          error.prependSegment(new Reporting.NameSegment("assetType"));
                          return error;
                        }));
      }
      if (thatDefaultThumbnail.isPresent()) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(thatDefaultThumbnail.get())
                    .flatMap(Verification::verifyToErrorStream)
                    .map(
                        error -> {
                          error.prependSegment(new Reporting.NameSegment("defaultThumbnail"));
                          return error;
                        }));
      }
      return errorStream;
    }

