    @Override
    public Stream<Reporting.Error> transformReference(IReference that) {
      Stream<Reporting.Error> errorStream = Stream.empty();
      final Optional<IReference> thatReferredSemanticId = that.getReferredSemanticId();
      if (!(that.getKeys().size() >= 1)) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n" + "Keys must contain at least one item.")));
      }
      if (!(!(that.getKeys().size() >= 1)
          || Constants.globallyIdentifiables.contains(
              ListHelpers.at(that.getKeys(), 0).getType()))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-121: For References the value of type of "
                            + "the first key of keys shall be one of Globally "
                            + "Identifiables.")));
      }
      if (!(!(that.getType() == ReferenceTypes.EXTERNAL_REFERENCE && that.getKeys().size() >= 1)
          || Constants.genericGloballyIdentifiables.contains(
              ListHelpers.at(that.getKeys(), 0).getType()))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-122: For external references the value of "
                            + "type of the first key of keys shall be one of Generic "
                            + "Globally Identifiables.")));
      }
      if (!(!(that.getType() == ReferenceTypes.MODEL_REFERENCE && that.getKeys().size() >= 1)
          || Constants.aasIdentifiables.contains(ListHelpers.at(that.getKeys(), 0).getType()))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-123: For model references the value of type "
                            + "of the first key of keys shall be one of AAS identifiables.")));
      }
      if (!(!(that.getType() == ReferenceTypes.EXTERNAL_REFERENCE)
          || (that.getKeys().stream()
              .allMatch(key -> !Constants.aasReferables.contains(key.getType()))))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-137: For external references, i.e. "
                            + "References with Reference/type = ExternalReference, "
                            + "the value of Key/type of any key in Reference/keys shall "
                            + "not be one of AAS referables.")));
      }
      if (!(!(that.getType() == ReferenceTypes.EXTERNAL_REFERENCE && that.getKeys().size() >= 1)
          || (Constants.genericGloballyIdentifiables.contains(
                  ListHelpers.at(that.getKeys(), -1).getType())
              || Constants.genericFragmentKeys.contains(
                  ListHelpers.at(that.getKeys(), -1).getType())))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-124: For external references the last key "
                            + "of keys shall be either one of Generic Globally "
                            + "Identifiables or one of Generic Fragment Keys.")));
      }
      if (!(!(that.getType() == ReferenceTypes.MODEL_REFERENCE && that.getKeys().size() > 1)
          || (IntStream.range(1, that.getKeys().size())
              .allMatch(
                  i ->
                      Constants.fragmentKeys.contains(
                          ListHelpers.at(that.getKeys(), i).getType()))))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-125: For model references with more than "
                            + "one key in keys the value of type of each of the keys "
                            + "following the first key of keys shall be one of Fragment "
                            + "Keys.")));
      }
      if (!(!(that.getType() == ReferenceTypes.MODEL_REFERENCE && that.getKeys().size() > 1)
          || (IntStream.range(0, that.getKeys().size() - 1)
              .allMatch(
                  i ->
                      !Constants.genericFragmentKeys.contains(
                          ListHelpers.at(that.getKeys(), i).getType()))))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-126: For model references with more than "
                            + "one key in keys the value of type of the last key in "
                            + "the reference key chain may be one of Generic Fragment Keys "
                            + "or no key at all shall have a value out of Generic Fragment "
                            + "Keys.")));
      }
      if (!(!(that.getType() == ReferenceTypes.MODEL_REFERENCE
              && that.getKeys().size() > 1
              && ListHelpers.at(that.getKeys(), -1).getType() == KeyTypes.FRAGMENT_REFERENCE)
          || (ListHelpers.at(that.getKeys(), -2).getType() == KeyTypes.FILE
              || ListHelpers.at(that.getKeys(), -2).getType() == KeyTypes.BLOB))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-127: For model references, with more than "
                            + "one key in keys a key with type Fragment Reference shall be "
                            + "preceded by a key with type File or Blob.")));
      }
      if (!(!(that.getType() == ReferenceTypes.MODEL_REFERENCE && that.getKeys().size() > 2)
          || (IntStream.range(0, that.getKeys().size() - 1)
              .allMatch(
                  i ->
                      !(ListHelpers.at(that.getKeys(), i).getType()
                              == KeyTypes.SUBMODEL_ELEMENT_LIST)
                          || matchesXsNonNegativeInteger(
                              ListHelpers.at(that.getKeys(), i + 1).getValue()))))) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(
                    new Reporting.Error(
                        "Invariant violated:\n"
                            + "Constraint AASd-128: For model references, the value of "
                            + "a key preceded by a key with type Submodel element list is "
                            + "an integer number denoting the position in the array of "
                            + "the submodel element list.")));
      }
      errorStream =
          Stream.<Reporting.Error>concat(
              errorStream,
              Stream.of(that.getType())
                  .flatMap(Verification::verifyReferenceTypes)
                  .map(
                      error -> {
                        error.prependSegment(new Reporting.NameSegment("type"));
                        return error;
                      }));
      if (thatReferredSemanticId.isPresent()) {
        errorStream =
            Stream.<Reporting.Error>concat(
                errorStream,
                Stream.of(thatReferredSemanticId.get())
                    .flatMap(Verification::verifyToErrorStream)
                    .map(
                        error -> {
                          error.prependSegment(new Reporting.NameSegment("referredSemanticId"));
                          return error;
                        }));
      }
      errorStream =
          Stream.<Reporting.Error>concat(
              errorStream,
              Stream.of(that.getKeys())
                  .flatMap(Verification::verifyListOf_IKey)
                  .map(
                      error -> {
                        error.prependSegment(new Reporting.NameSegment("keys"));
                        return error;
                      }));
      return errorStream;
    }

